def sample(self, batch_size: int) -> tuple[np.ndarray, ...]:
    indices = np.random.randint(0, self.size, size=batch_size)
    return (
        self.states[indices],
        self.mec_actions[indices],
        self.ratios[indices],
        self.rewards[indices],
        self.next_states[indices],
        self.dones[indices],
    )

def mlp(input_dim: int, hidden_dim: int, output_dim: int) -> nn.Sequential:
    return nn.Sequential(
        nn.Linear(input_dim, hidden_dim),
        nn.ReLU(),
        nn.Linear(hidden_dim, hidden_dim),
        nn.ReLU(),
        nn.Linear(hidden_dim, output_dim),
    )

@torch.no_grad()
def action(
    self, state: torch.Tensor, deterministic: bool
) -> tuple[int, float, float]:
    probs, _, ratios, _ = self.sample_all(state.unsqueeze(0), deterministic)
    if deterministic:
        mec = int(probs.argmax(dim=-1).item())
    else:
        mec = int(torch.multinomial(probs[0], 1).item())
    selected = ratios[0, mec]
    return mec, float(selected[0].item()), float(selected[1].item())

def forward(
    self, states: torch.Tensor, mec_actions: torch.Tensor, ratios: torch.Tensor
) -> torch.Tensor:
    one_hot = F.one_hot(mec_actions, num_classes=self.num_mec).float()
    return self.net(torch.cat((states, one_hot, ratios), dim=-1)).squeeze(-1)

@property
def alpha_discrete(self) -> torch.Tensor:
    return self.log_alpha_discrete.exp()

@property
def alpha_continuous(self) -> torch.Tensor:
    return self.log_alpha_continuous.exp()

def select_action(
    self, state: np.ndarray, deterministic: bool = False, random_action: bool = False
) -> tuple[int, float, float]:
    if random_action:
        return (
            int(np.random.randint(self.num_mec)),
            float(np.random.random()),
            float(np.random.random()),
        )
    state_t = torch.as_tensor(state, dtype=torch.float32, device=self.device)
    return self.actor.action(state_t, deterministic)

def _soft_update(self, target: nn.Module, source: nn.Module) -> None:
    with torch.no_grad():
        for target_param, source_param in zip(target.parameters(), source.parameters()):
            target_param.mul_(1.0 - self.cfg.target_tau).add_(
                source_param, alpha=self.cfg.target_tau
            )

def checkpoint_state(self) -> dict[str, object]:
    return {
        "actor": self.actor.state_dict(),
        "critic1": self.critic1.state_dict(),
        "critic2": self.critic2.state_dict(),
        "target1": self.target1.state_dict(),
        "target2": self.target2.state_dict(),
        "log_alpha_discrete": self.log_alpha_discrete.detach().cpu(),
        "log_alpha_continuous": self.log_alpha_continuous.detach().cpu(),
    }

@staticmethod
def _softplus_inverse(value: float) -> float:
    value = max(value, 1e-6)
    return math.log(math.expm1(value))

def _init_q_head(self) -> None:
    nn.init.uniform_(self.q_head.weight, -1e-3, 1e-3)
    nn.init.zeros_(self.q_head.bias)
